@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1135  cases=35
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-134
  @fn seedItems(h, takes, srcLen)  @ 150-155
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 157-166

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 170-178
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 181-190
  @case 'focusState before any render returns both bits false'  [harness]  @ 193-200
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 206-219
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 223-240
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 246-267
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 273-291
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 298-316
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 322-355
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 359-383
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 389-419
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 423-444
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 448-461
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 467-501
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 505-519
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 523-546
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 553-570
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 574-597
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 601-624
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 628-663
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 667-683
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 690-717
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 721-745
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 752-773
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 779-803
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 809-827
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 831-849
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 853-875
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 879-903
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 909-964
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 972-1001
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1007-1050
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1056-1070
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1077-1109
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1113-1133

